export const translations = { en, fr, ar, de } as const;
export type Language = keyof typeof translations;
export type TranslationKey = keyof typeof en;

export function translate(language: Language, key: TranslationKey, values?: Record<string, string | number>) {
  let text: string = translations[language][key] ?? en[key];
  for (const [name, value] of Object.entries(values ?? {})) text = text.replaceAll(`{{${name}}}`, String(value));
  return text;
}

export const LANGUAGE_LABELS: Record<Language, string> = { en: "English", fr: "Français", ar: "العربية", de: "Deutsch" };
